	b.custom_minimum_size = Vector2(BTN_W, BTN_H)
	b.add_theme_font_size_override("font_size", _fs(UiKit.FS_LG))
	b.add_theme_stylebox_override("normal", _btn_style(color, false))
	b.add_theme_stylebox_override("hover", _btn_style(color.lightened(0.18), true))
	b.add_theme_stylebox_override("pressed", _btn_style(color.darkened(0.25), false))
	b.add_theme_color_override("font_color", COL_TEXT)
	b.add_theme_color_override("font_hover_color", Color.WHITE)
	return b


