# 临时探针：主菜单「备战」入口按钮 rect / 按钮列总高，用完即删

func _ready() -> void:
	var lobby: Control = load("res://scenes/lobby.tscn").instantiate()
	add_child(lobby)
	for i in 4:
		await get_tree().process_frame
	var btns: Array = lobby.get("_menu_btns")
	print("viewport=", get_viewport().get_visible_rect().size, " menu_btns=", btns.size())
	var total := 0.0
	for b in btns:
		var btn := b as Button
		var r := btn.get_global_rect()
		total += r.size.y
		print("btn text=[", btn.text, "] rect=", r, " connections=", btn.pressed.get_connections().size())
	var col: VBoxContainer = btns[0].get_parent()
	print("col rect=", col.get_global_rect(), " sep=", col.get_theme_constant("separation"))
	print("4*96+3*20=", 4.0 * 96.0 + 3.0 * 20.0, " sum_btn_h=", total)
	var last: Button = btns[btns.size() - 1]
	print("last_bottom=", last.get_global_rect().end.y, " <= viewport_h=", get_viewport().get_visible_rect().size.y,
		" fits=", last.get_global_rect().end.y <= get_viewport().get_visible_rect().size.y)
	print("loadout scene exists=", ResourceLoader.exists("res://scenes/loadout.tscn"))
	get_tree().quit()
