Now `_on_begin_pick` + `_on_lobby_state` + `_process` + draft helpers.

Add `_process` near `_ready`/`_connect_signals`. Need to be careful: NetLobby extends Control; `_process` enabled by default.

Write draft helpers block — I'll insert after `_on_begin_pick` (host push) and a big helper block after `_leave_room` or near select section (after `_adopt_self_choice`).

Let me write:

```gdscript
func _on_begin_pick() -> void:
	if _role != 0:
		return
	_host_draft_reset()
	NetSession.begin_pick()
	_host_draft_push()
```

`_process`:
```gdscript
func _process(delta: float) -> void:
	# 顺序选人倒计时/推进（仅选人页；host 权威推进，guest 只本地递减显示）
	if _ui != UIState.SELECT or _draft_step < 0 or _draft_step >= SEL_DRAFT_ORDER.size():
		return
	_draft_left = maxf(0.0, _draft_left - delta)
	_tick_draft_ui()
	if _role == 0:
		_host_draft_tick(delta)
	else:
		_guest_draft_tick()
```

Host helpers:

```gdscript
# ---------- 顺序选人（host 权威） ----------

func _host_draft_reset() -> void:
	_draft_step = 0
	_draft_left = SEL_DRAFT_TURN_TIME
	_draft_turn = SEL_DRAFT_ORDER[0]
	_draft_picks = {}
	_draft_ai_timer = 0.0
	_draft_ai_wait = randf_range(1.2, 2.2)
	_draft_auto_sent = false


func _host_draft_push() -> void:
	NetSession.set_draft({
		"step": _draft_step,
		"left": _draft_left,
		"turn": _draft_turn,
		"picks": _draft_picks.duplicate(true),
	})


func _host_draft_advance() -> void:
	_draft_step += 1
	_draft_left = SEL_DRAFT_TURN_TIME
	_draft_ai_timer = 0.0
	_draft_ai_wait = randf_range(1.2, 2.2)
	_draft_turn = SEL_DRAFT_ORDER[_draft_step] if _draft_step < SEL_DRAFT_ORDER.size() else []
	_host_draft_push()


func _host_draft_tick(delta: float) -> void:
	if _draft_turn.size() < 2:
		return
	var team := int(_draft_turn[0])
	var seat := int(_draft_turn[1])
	var pid := _seat_peer(seat) if team == 0 else -1
	if pid > 0:
		# 真人回合：已锁定 → 推进；超时 1s → host 代选兜底（客户端自己 0s 会先自动选）
		if NetSession.get_picks().has(pid):
			_host_draft_advance()
		elif _draft_left <= 1.0:
			_host_auto_pick(pid)
		return
	# AI/敌方席位：像单机一样等 1~2s 再自动选
	_draft_ai_timer += delta
	if _draft_ai_timer >= _draft_ai_wait or _draft_left <= 0.0:
		_host_ai_pick(team, seat)


func _host_ai_pick(team: int, seat: int) -> void:
	var hero := _draft_pick_hero(team)
	_draft_picks["%d-%d" % [team, seat]] = hero
	_host_draft_advance()


func _host_auto_pick(pid: int) -> void:
	var hero := ""
	if pid == _self_peer():
		hero = _sel_hero if _hero_pickable(_sel_hero) else _random_lane_hero()
	if hero == "":
		hero = _draft_pick_hero(0)
	if hero == "":
		return
	if NetSession.host_force_pick(pid, hero, _sel_sid if (pid == _self_peer() and _sel_sid != "") else "flash"):
		_host_draft_advance()
```

Careful: `_host_auto_pick` when `host_force_pick` succeeds, `_picks` updated + broadcast; also `_host_draft_advance` → another push ✓. But `_host_draft_tick` next frame would see `_picks.has(pid)` and advance again → double advance! Because after auto pick, advance → new step; if new turn is another human who already... no, different pid. But if advance sets a turn where `_picks.has(pid)` is true (e.g. host's own pick exists and next human turn is host again? no, each seat once). Only risk: after auto-pick for pid, `_picks.has(pid)` true but step moved on. Fine.

However `_host_draft_advance` inside `_host_auto_pick` — then `_host_draft_tick` returns. Next frame checks new turn.

`_guest_draft_tick`:
```gdscript
func _guest_draft_tick() -> void:
	if not _draft_is_my_turn() or _draft_auto_sent or _draft_left > 0.0:
		return
	_draft_auto_sent = true
	var hero := _sel_hero if _hero_pickable(_sel_hero) else _random_lane_hero()
	if hero == "":
		return
	NetSession.send_pick(hero, _sel_sid if _sel_sid != "" else "flash")
	_show_pick_error("超时自动锁定 %s" % hero)   # 用状态行提示（COL_ERR？better COL_SUB）
```
Use `_pick_status` with COL_SUB not error. Write inline.

Helpers:

```gdscript
func _draft_active() -> bool:
	return _draft_step >= 0 and _draft_step < SEL_DRAFT_ORDER.size()


func _draft_done() -> bool:
	return _draft_step >= SEL_DRAFT_ORDER.size()


func _draft_is_my_turn() -> bool:
	if not _draft_active() or _draft_turn.size() < 2:
		return false
	return int(_draft_turn[0]) == 0 and int(_draft_turn[1]) == _my_seat - 1


func _seat_peer(seat: int) -> int:
	var ids := NetSession.active_player_ids()
	if seat < 0 or seat >= ids.size():
		return -1
	return int(ids[seat])


func _hero_pickable(hname: String) -> bool:
	if hname == "" or not HeroPickData.HERO_ROLE.has(hname):
		return false
	var role := str(HeroPickData.HERO_ROLE[hname])
	if _draft_taken.has(hname) or _blocked_roles.has(role):
		return false
	if _lane_locked and role != _lane_role:
		return false
	return true


func _random_lane_hero() -> String:
	var pool: Array = []
	for hn in HeroPickData.HERO_ROLE:
		var h := str(hn)
		if str(HeroPickData.HERO_ROLE[h]) != _lane_role:
			continue
		if _hero_pickable(h):
			pool.append(h)
	if pool.is_empty():
		for hn in HeroPickData.HERO_ROLE:
			if _hero_pickable(str(hn)):
				pool.append(str(hn))
	if pool.is_empty():
		return ""
	return str(pool[randi() % pool.size()])


# host：按队内职责唯一 + 全局唯一挑一名展示用英雄（我方 AI 不占房主分路，同单机语义）
func _draft_pick_hero(team: int) -> String:
	var used := {}
	var roles := {}
	var picks := NetSession.get_picks()
	for k in _draft_picks:
		var h := str(_draft_picks[k])
		used[h] = true
		if int(str(k).split("-")[0]) == team:
			roles[str(HeroPickData.HERO_ROLE.get(h, ""))] = true
	for pid in picks:
		var h2 := str(picks[pid].get("hero", ""))
		used[h2] = true
		roles[str(picks[pid].get("role", ""))] = true
	var pool: Array = []
	var fallback: Array = []
	for hn in HeroPickData.HERO_ROLE:
		var h3 := str(hn)
		if used.has(h3):
			continue
		var role := str(HeroPickData.HERO_ROLE[h3])
		fallback.append(h3)
		if roles.has(role):
			continue
		if team == 0 and role == _lane_role:
			continue
		pool.append(h3)
	if pool.is_empty():
		pool = fallback
	if pool.is_empty():
		return ""
	return str(pool[randi() % pool.size()])


func _draft_turn_side() -> String:
	if _draft_turn.size() < 2:
		return ""
	return "蓝方" if int(_draft_turn[0]) == 0 else "红方"


func _draft_turn_label() -> String:
	if _draft_turn.size() < 2:
		return ""
	var team := int(_draft_turn[0])
	var seat := int(_draft_turn[1])
	if team == 1:
		return "红方 %d 号位" % (seat + 1)
	var pid := _seat_peer(seat)
	if pid <= 0:
		return "我方 %d 号位 · AI" % (seat + 1)
	return "我方 %d 号位 · %s" % [seat + 1, _player_name(pid, _last_state)]


func _draft_title_text() -> String:
	if _draft_done():
		return "双方阵容已定"
	if not _draft_active():
		return "选择英雄"
	return "第 %d/10 步 · %s 选人" % [_draft_step + 1, _draft_turn_label()]


func _draft_sub_text() -> String:
	if _draft_done():
		return "全员锁定后由房主开始对局"
	if not _draft_active():
		return ""
	var left := int(ceil(maxf(0.0, _draft_left)))
	if _draft_is_my_turn():
		return "轮到你选 · 剩余 %ds · 点英雄卡 → 召唤师 → 锁定" % left
	return "等待 %s · 剩余 %ds" % [_draft_turn_label(), left]


func _tick_draft_ui() -> void:
	if _stage_title != null:
		_stage_title.text = _draft_title_text()
	if _stage_sub != null:
		_stage_sub.text = _draft_sub_text()
	if _countdown_lab != null:
		_countdown_lab.text = str(int(ceil(maxf(0.0, _draft_left)))) if _draft_active() else ("✓" if _draft_done() else "∞")
```

Careful: `_draft_title_text` uses `_player_name(pid, _last_state)` which appends "（本机）" for self — that's fine/desired.

