{"file_path":"scripts/net/NetSession.gd","new_string":"# 顺序选人合法性：本回合玩家才可上报；展示阵容里的英雄/职责不重复
func _draft_allows(pid: int, hero: String) -> bool:
	if draft.is_empty():
		return true
	if int(draft.get("step", 0)) >= 10:
		return not _picks.has(pid)   # 顺序已结束：只允许补未锁席位，不允许改选","old_string":"# 顺序选人合法性：本回合玩家才可上报；展示阵容里的英雄/职责不重复
func _draft_allows(pid: int, hero: String) -> bool:
	if draft.is_empty():
		return true
	if int(draft.get("step", 0)) >= 10:
		return false   # 顺序已完成"}

