{"content":"extends Node
# 临时探针：联机自动开局 + 加载层（host / guest 共用，-- 后跟 host|guest）

func _ready() -> void:
	var k := _K.new()
	k.host_mode = not OS.get_cmdline_user_args().has("guest")
	k.name = "ProbeNetKeeper"
	get_tree().root.add_child.call_deferred(k)


class _K extends Node:
	var host_mode := true
	var lobby: Control

	func _ready() -> void:
		call_deferred("_run")

	func f(n: int) -> void:
		for i in n:
			await get_tree().process_frame

	func _my_pid() -> int:
		if NetSession.mode == NetSession.Mode.CLIENT:
			return multiplayer.get_unique_id()
		return 1

	func _run() -> void:
		PlayerPrefs.set_lane("对抗路")
		var tag := "H" if host_mode else "C"
		if host_mode:
			NetSession.host_game(7313)
		else:
			NetSession.join_game("127.0.0.1", 7313)
		lobby = load("res://scenes/lobby.tscn").instantiate()
		add_child(lobby)
		await f(4)
		var g := 0
		if host_mode:
			while NetSession.players.size() < 2 and g < 1200:
				g += 1
				await f(1)
			lobby.set("_role", 0)
			lobby.call("_on_begin_pick")
			print("[", tag, "] 进房=", NetSession.players.size(), " begin step=", lobby.get("_draft_step"))
		var locked_at := -1
		g = 0
		while g < 2400 and NetSession.phase != NetSession.Phase.BATTLE:
			g += 1
			if bool(lobby.call("_draft_is_my_turn")) and not NetSession.get_picks().has(_my_pid()):
				var h := str(lobby.call("_random_lane_hero"))
				if h == "":
					h = str(lobby.call("_draft_pick_hero", 0))
				lobby.set("_sel_hero", h)
				lobby.set("_sel_sid", "flash")
				lobby.set("_sel_summ", "闪现")
				lobby.call("_sync_pick_ui")
				lobby.call("_on_pick_confirm")
				print("[", tag, "] 我的回合锁定 ", h, " step=", lobby.get("_draft_step"))
			if host_mode and locked_at < 0 and NetSession._all_active_picked() and int(lobby.get("_draft_step")) >= 10:
				locked_at = Time.get_ticks_msec()
				print("[", tag, "] 全员锁定 step=", lobby.get("_draft_step"), " 文案=[", lobby.get("_auto_start_lab").text, "]")
			await f(1)
		var dt := Time.get_ticks_msec() - locked_at if locked_at >= 0 else -1
		print("[", tag, "] BATTLE phase=", NetSession.phase, " 自动开局耗时=", dt, "ms 加载层=",
			lobby.get("_loading") != null, " 待切=", lobby.get("_route_pending"), " 已切=", lobby.get("_route_count"))
		g = 0
		while int(lobby.get("_route_count")) < 1 and g < 900:
			g += 1
			await f(1)
		await f(6)
		var cs := get_tree().current_scene
		print("[", tag, "] 切场景 次数=", lobby.get("_route_count"), " scene=",
			cs.scene_file_path if cs != null else "null")
		await f(120)
		get_tree().quit()
","file_path":"_probe_net_auto.gd"}

